window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-157b8133bef0a3d6"]={"versions": [{"id": "FIG-157b8133bef0a3d6", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / AUTOSAR-Metamodellausschnitt (M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R22-11 (<em>Specification of Manifest</em> / Software Distribution & Execution Management).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Zuordnung zwischen deploybaren Software-Einheiten (<code>SoftwareCluster</code>) und den Zustandssteuerungs-Domänen der Maschine (<code>FunctionGroupSet</code> bzw. <code>ModeDeclarationGroupPrototype</code>). Es modelliert das formale Bindeglied zwischen Update- & Konfigurationsmanagement (UCM) und dem Execution Management (EM) zur kontrollierten Zuweisung von Funktionsgruppen an Software-Cluster.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>FunctionGroupSet</code></strong></li>\n<li><em>Stereotypen / Basistypen:</em> <code>«ARElement»</code>, <code>«AtpClassifier»</code> (abstrakter Typ-Klassifizierer im AUTOSAR-Metamodell).</li>\n<li><em>Rolle:</em> Repräsentiert die Aggregation aller Funktionsgruppen, die für eine Maschine (Machine Manifest) definiert sind.</li>\n<li><strong><code>ModeDeclarationGroupPrototype</code></strong></li>\n<li><em>Stereotyp:</em> <code>«AtpPrototype»</code> (Instanziierungs-Prototyp im Template-Konzept).</li>\n<li><em>Rolle:</em> Konkrete Ausprägung einer Funktionsgruppe (z. B. <code>MachineState</code> oder domänenspezifische Funktionsgruppen). Bildet die Schnittstelle zu den auswählbaren Betriebsmodi (Modes).</li>\n<li><strong><code>SoftwareCluster</code></strong></li>\n<li><em>Stereotyp:</em> <code>«ARElement»</code>.</li>\n<li><em>Rolle:</em> Unabhängig paketierbare, signierbare und aktualisierbare logische Einheit von Applikationen/Diensten auf der Adaptive Platform.</li>\n<li><em>Attribute:</em></li>\n<li><code>+installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code> – Definiert Entfernungs-/Update-Eigenschaften (<code>canBeRemoved</code>, <code>cannotBeRemoved</code>).</li>\n<li><code>+typeApproval: String [0..1]</code> – Typgenehmigungs- bzw. Homologations-Identifikator.</li>\n<li><code>+vendorId: PositiveInteger [0..1]</code> – Herstellerkennung.</li>\n<li><code>+version: StrongRevisionLabelString [0..1]</code> – Streng typisierte Versionskennung (SemVer-kompatibles Format).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><code>FunctionGroupSet</code> $\\blacklozenge\\xrightarrow{\\text{+functionGroup [0..*]}}$ <code>ModeDeclarationGroupPrototype</code>: Strikte Komposition. Die Lebensdauer der Funktionsgruppen-Prototypen ist an das umschließende Set gebunden.</li>\n<li><code>SoftwareCluster</code> $\\longrightarrow^{\\text{+claimedFunctionGroup [0..*]}}$ <code>ModeDeclarationGroupPrototype</code>: Gerichtete Assoziation (Referenz). Ein <code>SoftwareCluster</code> beansprucht die funktionale Zuständigkeit für null bis viele Funktionsgruppen, ohne deren Eigentümer im Maschinen-Definitionskontext zu sein.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (Manifest- &amp; Laufzeit-Abbildung)</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, leitet sich das dynamische Verhalten aus der Interaktion zwischen UCM und EM ab:</p>\n<ol class=\"fig-list\">\n<li><strong>Deployment / Aktivierungsphase (UCM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das UCM verifiziert bei Installation/Aktualisierung eines <code>SoftwareCluster</code> anhand von <code>claimedFunctionGroup</code>, ob die geforderten Funktionsgruppen auf der Zielmaschine deklariert sind.</li>\n<li>Validierung von Signatur und Version (<code>vendorSignature</code>, <code>version</code>, <code>vendorId</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeit-Initialisierung & Moduswechsel (EM & SM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Execution Management bindet die Prozessdefinitionen des <code>SoftwareCluster</code> an die Zustände der referenzierten <code>claimedFunctionGroup</code>.</li>\n<li>State Management fordert über <code>ara::exec::StateClient</code> Modusübergänge auf den Funktionsgruppen an.</li>\n<li>EM aktiviert/terminiert Prozesse im <code>SoftwareCluster</code> deterministisch anhand der Zustandsdefinitionen der deklarierten Funktionsgruppen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deinstallations-/Update-Regeln:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist <code>installationBehavior == cannotBeRemoved</code>, weist das UCM Löschanfragen ab und lässt ausschließlich Version-Rollbacks oder Vorwärts-Updates zu.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Split & ARXML-Trennung:</strong></li>\n<li><code>FunctionGroupSet</code> und <code>ModeDeclarationGroupPrototype</code> werden primär im <strong>Machine Manifest</strong> konfiguriert (maschinenweit gültig).</li>\n<li><code>SoftwareCluster</code> und dessen Referenz <code>claimedFunctionGroup</code> liegen im <strong>Software Cluster Manifest</strong> (anwendungs-/lieferantenbezogen). Entwickler müssen sicherstellen, dass die symbolischen Pfade (Short-Name-Pfade) zur Compile-/Packaging-Zeit auflösbar sind.</li>\n<li><strong>Normative Constraints:</strong></li>\n<li><code>[constr_10410]</code>: Handelt es sich um einen Cluster der Kategorie <code>PLATFORM_CORE</code>, <strong>muss</strong> <code>installationBehavior</code> zwingend auf <code>cannotBeRemoved</code> gesetzt sein (Basisplattform darf nicht deinstalliert werden).</li>\n<li><code>[constr_10233]</code>, <code>[constr_10234]</code>, <code>[constr_10235]</code>: Nach Abschluss der Manifest-Generierung müssen <code>vendorSignature</code>, <code>version</code> und <code>vendorId</code> zwingend vorhanden sein (Multiplizität faktisch <code>[1..1]</code> im finalen Build-Artefakt).</li>\n<li><strong>Einschränkung für Integratoren:</strong> Mehrere Software-Cluster können dieselbe Funktionsgruppe beanspruchen, sofern die darin definierten Prozessstarts und State-Mappings kollisionsfrei im Gesamtsystem harmonisiert sind. Die Verknüpfung steuert direkt das Process-Execution-State-Reporting an das Execution Management.</li>\n</ul>"}, {"id": "FIG-e119292d1a2e2f99", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / AUTOSAR-Metamodellausschnitt (M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R22-11 (<em>Specification of Manifest</em> / Software Distribution & Execution Management).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Zuordnung zwischen deploybaren Software-Einheiten (<code>SoftwareCluster</code>) und den Zustandssteuerungs-Domänen der Maschine (<code>FunctionGroupSet</code> bzw. <code>ModeDeclarationGroupPrototype</code>). Es modelliert das formale Bindeglied zwischen Update- & Konfigurationsmanagement (UCM) und dem Execution Management (EM) zur kontrollierten Zuweisung von Funktionsgruppen an Software-Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>FunctionGroupSet</code></strong></li>\n<li><em>Stereotypen / Basistypen:</em> <code>«AtpClassifier»</code>, <code>«UploadableDesignElement»</code>.</li>\n<li><em>Rolle:</em> Repräsentiert die Aggregation aller Funktionsgruppen, die für eine Maschine (Machine Manifest) definiert sind.</li>\n<li><strong><code>ModeDeclarationGroupPrototype</code></strong></li>\n<li><em>Stereotyp:</em> <code>«AtpPrototype»</code> (Instanziierungs-Prototyp im Template-Konzept).</li>\n<li><em>Rolle:</em> Konkrete Ausprägung einer Funktionsgruppe (z. B. <code>MachineState</code> oder domänenspezifische Funktionsgruppen). Bildet die Schnittstelle zu den auswählbaren Betriebsmodi (Modes).</li>\n<li><strong><code>SoftwareCluster</code></strong></li>\n<li><em>Stereotyp:</em> <code>«UploadableDeploymentElement»</code>.</li>\n<li><em>Rolle:</em> Unabhängig paketierbare, signierbare und aktualisierbare logische Einheit von Applikationen/Diensten auf der Adaptive Platform.</li>\n<li><em>Attribute:</em></li>\n<li><code>+installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code> – Definiert Entfernungs-/Update-Eigenschaften (<code>canBeRemoved</code>, <code>cannotBeRemoved</code>).</li>\n<li><code>+typeApproval: String [0..1]</code> – Typgenehmigungs- bzw. Homologations-Identifikator.</li>\n<li><code>+vendorId: PositiveInteger [0..1]</code> – Herstellerkennung.</li>\n<li><code>+version: StrongRevisionLabelString [0..1]</code> – Streng typisierte Versionskennung (SemVer-kompatibles Format).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><code>FunctionGroupSet</code> $\\blacklozenge\\xrightarrow{\\text{+functionGroup [0..*]}}$ <code>ModeDeclarationGroupPrototype</code>: Strikte Komposition. Die Lebensdauer der Funktionsgruppen-Prototypen ist an das umschließende Set gebunden.</li>\n<li><code>SoftwareCluster</code> $\\longrightarrow^{\\text{+claimedFunctionGroup [0..*]}}$ <code>ModeDeclarationGroupPrototype</code>: Gerichtete Assoziation (Referenz). Ein <code>SoftwareCluster</code> beansprucht die funktionale Zuständigkeit für null bis viele Funktionsgruppen, ohne deren Eigentümer im Maschinen-Definitionskontext zu sein.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, leitet sich das dynamische Verhalten aus der Interaktion zwischen UCM und EM ab:</p>\n<ol class=\"fig-list\">\n<li><strong>Deployment / Aktivierungsphase (UCM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das UCM verifiziert bei Installation/Aktualisierung eines <code>SoftwareCluster</code> anhand von <code>claimedFunctionGroup</code>, ob die geforderten Funktionsgruppen auf der Zielmaschine deklariert sind.</li>\n<li>Validierung von Signatur und Version (<code>vendorSignature</code>, <code>version</code>, <code>vendorId</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeit-Initialisierung & Moduswechsel (EM & SM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Execution Management bindet die Prozessdefinitionen des <code>SoftwareCluster</code> an die Zustände der referenzierten <code>claimedFunctionGroup</code>.</li>\n<li>State Management fordert über <code>ara::exec::StateClient</code> Modusübergänge auf den Funktionsgruppen an.</li>\n<li>EM aktiviert/terminiert Prozesse im <code>SoftwareCluster</code> deterministisch anhand der Zustandsdefinitionen der deklarierten Funktionsgruppen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deinstallations-/Update-Regeln:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist <code>installationBehavior == cannotBeRemoved</code>, weist das UCM Löschanfragen ab und lässt ausschließlich Version-Rollbacks oder Vorwärts-Updates zu.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Split & ARXML-Trennung:</strong></li>\n<li><code>FunctionGroupSet</code> und <code>ModeDeclarationGroupPrototype</code> werden primär im <strong>Machine Manifest</strong> konfiguriert (maschinenweit gültig).</li>\n<li><code>SoftwareCluster</code> und dessen Referenz <code>claimedFunctionGroup</code> liegen im <strong>Software Cluster Manifest</strong> (anwendungs-/lieferantenbezogen). Entwickler müssen sicherstellen, dass die symbolischen Pfade (Short-Name-Pfade) zur Compile-/Packaging-Zeit auflösbar sind.</li>\n<li><strong>Normative Constraints:</strong></li>\n<li><code>[constr_10410]</code>: Handelt es sich um einen Cluster der Kategorie <code>PLATFORM_CORE</code>, <strong>muss</strong> <code>installationBehavior</code> zwingend auf <code>cannotBeRemoved</code> gesetzt sein (Basisplattform darf nicht deinstalliert werden).</li>\n<li><code>[constr_10233]</code>, <code>[constr_10234]</code>, <code>[constr_10235]</code>: Nach Abschluss der Manifest-Generierung müssen <code>vendorSignature</code>, <code>version</code> und <code>vendorId</code> zwingend vorhanden sein (Multiplizität faktisch <code>[1..1]</code> im finalen Build-Artefakt).</li>\n<li><strong>Einschränkung für Integratoren:</strong> Mehrere Software-Cluster können dieselbe Funktionsgruppe beanspruchen, sofern die darin definierten Prozessstarts und State-Mappings kollisionsfrei im Gesamtsystem harmonisiert sind. Die Verknüpfung steuert direkt das Process-Execution-State-Reporting an das Execution Management.</li>\n</ul>"}, {"id": "FIG-8eef7431cd070b05", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / AUTOSAR-Metamodellausschnitt (M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R22-11 (<em>Specification of Manifest</em> / Software Distribution & Execution Management).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Zuordnung zwischen deploybaren Software-Einheiten (<code>SoftwareCluster</code>) und den Zustandssteuerungs-Domänen der Maschine (<code>FunctionGroupSet</code> bzw. <code>ModeDeclarationGroupPrototype</code>). Es modelliert das formale Bindeglied zwischen Update- & Konfigurationsmanagement (UCM) und dem Execution Management (EM) zur kontrollierten Zuweisung von Funktionsgruppen an Software-Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>FunctionGroupSet</code></strong></li>\n<li><em>Stereotypen / Basistypen:</em> <code>«AtpClassifier»</code>, <code>«UploadableDesignElement»</code>.</li>\n<li><em>Rolle:</em> Repräsentiert die Aggregation aller Funktionsgruppen, die für eine Maschine (Machine Manifest) definiert sind.</li>\n<li><strong><code>ModeDeclarationGroupPrototype</code></strong></li>\n<li><em>Stereotyp:</em> <code>«AtpPrototype»</code> (Instanziierungs-Prototyp im Template-Konzept).</li>\n<li><em>Rolle:</em> Konkrete Ausprägung einer Funktionsgruppe (z. B. <code>MachineState</code> oder domänenspezifische Funktionsgruppen). Bildet die Schnittstelle zu den auswählbaren Betriebsmodi (Modes).</li>\n<li><strong><code>SoftwareCluster</code></strong></li>\n<li><em>Stereotyp:</em> <code>«UploadableDeploymentElement»</code>.</li>\n<li><em>Rolle:</em> Unabhängig paketierbare, signierbare und aktualisierbare logische Einheit von Applikationen/Diensten auf der Adaptive Platform.</li>\n<li><em>Attribute:</em></li>\n<li><code>+installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code> – Definiert Entfernungs-/Update-Eigenschaften (<code>canBeRemoved</code>, <code>cannotBeRemoved</code>).</li>\n<li><code>+typeApproval: String [0..1]</code> – Typgenehmigungs- bzw. Homologations-Identifikator.</li>\n<li><code>+vendorId: PositiveInteger [0..1]</code> – Herstellerkennung.</li>\n<li><code>+version: StrongRevisionLabelString [0..1]</code> – Streng typisierte Versionskennung (SemVer-kompatibles Format).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><code>FunctionGroupSet</code> $\\blacklozenge\\xrightarrow{\\text{+functionGroup [0..*]}}$ <code>ModeDeclarationGroupPrototype</code>: Strikte Komposition. Die Lebensdauer der Funktionsgruppen-Prototypen ist an das umschließende Set gebunden.</li>\n<li><code>SoftwareCluster</code> $\\longrightarrow^{\\text{+claimedFunctionGroup [0..*]}}$ <code>ModeDeclarationGroupPrototype</code>: Gerichtete Assoziation (Referenz). Ein <code>SoftwareCluster</code> beansprucht die funktionale Zuständigkeit für null bis viele Funktionsgruppen, ohne deren Eigentümer im Maschinen-Definitionskontext zu sein.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, leitet sich das dynamische Verhalten aus der Interaktion zwischen UCM und EM ab:</p>\n<ol class=\"fig-list\">\n<li><strong>Deployment / Aktivierungsphase (UCM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das UCM verifiziert bei Installation/Aktualisierung eines <code>SoftwareCluster</code> anhand von <code>claimedFunctionGroup</code>, ob die geforderten Funktionsgruppen auf der Zielmaschine deklariert sind.</li>\n<li>Validierung von Signatur und Version (<code>vendorSignature</code>, <code>version</code>, <code>vendorId</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeit-Initialisierung & Moduswechsel (EM & SM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Execution Management bindet die Prozessdefinitionen des <code>SoftwareCluster</code> an die Zustände der referenzierten <code>claimedFunctionGroup</code>.</li>\n<li>State Management fordert über <code>ara::exec::StateClient</code> Modusübergänge auf den Funktionsgruppen an.</li>\n<li>EM aktiviert/terminiert Prozesse im <code>SoftwareCluster</code> deterministisch anhand der Zustandsdefinitionen der deklarierten Funktionsgruppen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deinstallations-/Update-Regeln:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist <code>installationBehavior == cannotBeRemoved</code>, weist das UCM Löschanfragen ab und lässt ausschließlich Version-Rollbacks oder Vorwärts-Updates zu.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Split & ARXML-Trennung:</strong></li>\n<li><code>FunctionGroupSet</code> und <code>ModeDeclarationGroupPrototype</code> werden primär im <strong>Machine Manifest</strong> konfiguriert (maschinenweit gültig).</li>\n<li><code>SoftwareCluster</code> und dessen Referenz <code>claimedFunctionGroup</code> liegen im <strong>Software Cluster Manifest</strong> (anwendungs-/lieferantenbezogen). Entwickler müssen sicherstellen, dass die symbolischen Pfade (Short-Name-Pfade) zur Compile-/Packaging-Zeit auflösbar sind.</li>\n<li><strong>Normative Constraints:</strong></li>\n<li><code>[constr_10410]</code>: Handelt es sich um einen Cluster der Kategorie <code>PLATFORM_CORE</code>, <strong>muss</strong> <code>installationBehavior</code> zwingend auf <code>cannotBeRemoved</code> gesetzt sein (Basisplattform darf nicht deinstalliert werden).</li>\n<li><code>[constr_10233]</code>, <code>[constr_10234]</code>, <code>[constr_10235]</code>: Nach Abschluss der Manifest-Generierung müssen <code>vendorSignature</code>, <code>version</code> und <code>vendorId</code> zwingend vorhanden sein (Multiplizität faktisch <code>[1..1]</code> im finalen Build-Artefakt).</li>\n<li><strong>Einschränkung für Integratoren:</strong> Mehrere Software-Cluster können dieselbe Funktionsgruppe beanspruchen, sofern die darin definierten Prozessstarts und State-Mappings kollisionsfrei im Gesamtsystem harmonisiert sind. Die Verknüpfung steuert direkt das Process-Execution-State-Reporting an das Execution Management.</li>\n</ul>"}, {"id": "FIG-6ee8c726301ef264", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / AUTOSAR-Metamodellausschnitt (M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R22-11 (<em>Specification of Manifest</em> / Software Distribution & Execution Management).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der strukturellen Zuordnung zwischen deploybaren Software-Einheiten (<code>SoftwareCluster</code>) und den Zustandssteuerungs-Domänen der Maschine (<code>FunctionGroupSet</code> bzw. <code>ModeDeclarationGroupPrototype</code>). Es modelliert das formale Bindeglied zwischen Update- & Konfigurationsmanagement (UCM) und dem Execution Management (EM) zur kontrollierten Zuweisung von Funktionsgruppen an Software-Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>FunctionGroupSet</code></strong></li>\n<li><em>Stereotypen / Basistypen:</em> <code>«AtpClassifier»</code>, <code>«UploadableDesignElement»</code>.</li>\n<li><em>Rolle:</em> Repräsentiert die Aggregation aller Funktionsgruppen, die für eine Maschine (Machine Manifest) definiert sind.</li>\n<li><strong><code>ModeDeclarationGroupPrototype</code></strong></li>\n<li><em>Stereotyp:</em> <code>«AtpPrototype»</code> (Instanziierungs-Prototyp im Template-Konzept).</li>\n<li><em>Rolle:</em> Konkrete Ausprägung einer Funktionsgruppe (z. B. <code>MachineState</code> oder domänenspezifische Funktionsgruppen). Bildet die Schnittstelle zu den auswählbaren Betriebsmodi (Modes).</li>\n<li><strong><code>SoftwareCluster</code></strong></li>\n<li><em>Stereotyp:</em> <code>«UploadableDeploymentElement»</code>.</li>\n<li><em>Rolle:</em> Unabhängig paketierbare, signierbare und aktualisierbare logische Einheit von Applikationen/Diensten auf der Adaptive Platform.</li>\n<li><em>Attribute:</em></li>\n<li><code>+typeApproval: String [0..1]</code> – Typgenehmigungs- bzw. Homologations-Identifikator.</li>\n<li><code>+vendorId: PositiveInteger [0..1]</code> – Herstellerkennung.</li>\n<li><code>+version: StrongRevisionLabelString [0..1]</code> – Streng typisierte Versionskennung (SemVer-kompatibles Format).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li><code>FunctionGroupSet</code> $\\blacklozenge\\xrightarrow{\\text{+functionGroup [0..*]}}$ <code>ModeDeclarationGroupPrototype</code>: Strikte Komposition. Die Lebensdauer der Funktionsgruppen-Prototypen ist an das umschließende Set gebunden.</li>\n<li><code>SoftwareCluster</code> $\\longrightarrow^{\\text{+claimedFunctionGroup [0..*]}}$ <code>ModeDeclarationGroupPrototype</code>: Gerichtete Assoziation (Referenz). Ein <code>SoftwareCluster</code> beansprucht die funktionale Zuständigkeit für null bis viele Funktionsgruppen, ohne deren Eigentümer im Maschinen-Definitionskontext zu sein.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein statisches Metamodell handelt, leitet sich das dynamische Verhalten aus der Interaktion zwischen UCM und EM ab:</p>\n<ol class=\"fig-list\">\n<li><strong>Deployment / Aktivierungsphase (UCM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das UCM verifiziert bei Installation/Aktualisierung eines <code>SoftwareCluster</code> anhand von <code>claimedFunctionGroup</code>, ob die geforderten Funktionsgruppen auf der Zielmaschine deklariert sind.</li>\n<li>Validierung von Signatur und Version (<code>vendorSignature</code>, <code>version</code>, <code>vendorId</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Laufzeit-Initialisierung & Moduswechsel (EM & SM):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Execution Management bindet die Prozessdefinitionen des <code>SoftwareCluster</code> an die Zustände der referenzierten <code>claimedFunctionGroup</code>.</li>\n<li>State Management fordert über <code>ara::exec::StateClient</code> Modusübergänge auf den Funktionsgruppen an.</li>\n<li>EM aktiviert/terminiert Prozesse im <code>SoftwareCluster</code> deterministisch anhand der Zustandsdefinitionen der deklarierten Funktionsgruppen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Deinstallations-/Update-Regeln:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist <code>installationBehavior == cannotBeRemoved</code>, weist das UCM Löschanfragen ab und lässt ausschließlich Version-Rollbacks oder Vorwärts-Updates zu.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Split & ARXML-Trennung:</strong></li>\n<li><code>FunctionGroupSet</code> und <code>ModeDeclarationGroupPrototype</code> werden primär im <strong>Machine Manifest</strong> konfiguriert (maschinenweit gültig).</li>\n<li><code>SoftwareCluster</code> und dessen Referenz <code>claimedFunctionGroup</code> liegen im <strong>Software Cluster Manifest</strong> (anwendungs-/lieferantenbezogen). Entwickler müssen sicherstellen, dass die symbolischen Pfade (Short-Name-Pfade) zur Compile-/Packaging-Zeit auflösbar sind.</li>\n<li><strong>Normative Constraints:</strong></li>\n<li><code>[constr_10410]</code>: Handelt es sich um einen Cluster der Kategorie <code>PLATFORM_CORE</code>, <strong>muss</strong> <code>installationBehavior</code> zwingend auf <code>cannotBeRemoved</code> gesetzt sein (Basisplattform darf nicht deinstalliert werden).</li>\n<li><code>[constr_10233]</code>, <code>[constr_10234]</code>, <code>[constr_10235]</code>: Nach Abschluss der Manifest-Generierung müssen <code>vendorSignature</code>, <code>version</code> und <code>vendorId</code> zwingend vorhanden sein (Multiplizität faktisch <code>[1..1]</code> im finalen Build-Artefakt).</li>\n<li><strong>Einschränkung für Integratoren:</strong> Mehrere Software-Cluster können dieselbe Funktionsgruppe beanspruchen, sofern die darin definierten Prozessstarts und State-Mappings kollisionsfrei im Gesamtsystem harmonisiert sind. Die Verknüpfung steuert direkt das Process-Execution-State-Reporting an das Execution Management.</li>\n</ul>"}], "trans": [{"from": "FIG-157b8133bef0a3d6", "to": "FIG-e119292d1a2e2f99", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>FunctionGroupSet:</strong> Das Metamodell-Element spezialisiert nun <code>UploadableDesignElement</code> anstelle von <code>ARElement</code> (Stereotyp/Klassifikator <code>AtpClassifier</code> bleibt bestehen).</li>\n<li><strong>SoftwareCluster:</strong> Das Element spezialisiert nun <code>UploadableDeploymentElement</code> anstelle von <code>ARElement</code>.</li>\n</ul>"}, {"from": "FIG-e119292d1a2e2f99", "to": "FIG-8eef7431cd070b05", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>FunctionGroupSet:</strong> Die Kastenbreite wurde vergrößert, sodass die Beschriftung <code>UploadableDesignElement</code> vollständig innerhalb der Box liegt und der vorherige Textüberlauf behoben ist; die Abstände und horizontalen Positionen der Folgeelemente wurden im Layout angepasst.</li>\n</ul>"}, {"from": "FIG-8eef7431cd070b05", "to": "FIG-6ee8c726301ef264", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>SoftwareCluster:</strong> Das Attribut <code>+ installationBehavior: SoftwareClusterInstallationBehaviorEnum [0..1]</code> wurde entfernt.</li>\n</ul>"}]};
